// Gate for every Breakpoint podcast request: team passcode, approved email, and at least one link or a brief.
// TEAM_PASSCODE: Billy types the passcode here in n8n himself. Blank = nothing is accepted.
const TEAM_PASSCODE = '';
const ALLOWED = ['breakpointsystems.com', 'agencyhlpc.com', 'thejordaninsuranceagency.com'];
const f = $input.first().json;
const given = String(f.passcode || '').trim();
const email = String(f.work_email || '').trim().toLowerCase();
const domain = email.includes('@') ? email.split('@').pop() : '';
const emailOk = /^[^@\s]+@[^@\s]+\.[a-z]{2,}$/.test(email) && ALLOWED.includes(domain);
const links = [...new Set(String(f.links || '').split(/\s+/).map(s => s.trim().replace(/[),.;]+$/, '')).filter(s => /^https?:\/\/[^\s\/]+\.[^\s\/]+/i.test(s)))].slice(0, 7);
const brief = String(f.brief || '').trim();
const ad = String(f.air_date || '').trim().slice(0, 10);
const reason = !TEAM_PASSCODE ? 'passcode not set up yet: Billy types it into the Check Requester node' : given !== TEAM_PASSCODE ? 'wrong team passcode' : !emailOk ? 'not an approved email domain' : (!links.length && brief.length < 200) ? 'no links and no brief (a brief needs at least a few sentences)' : '';
return [{ json: { allowed: reason === '', reason, email, link_list: links.join('\n'), brief, count: links.length + (brief.length >= 200 ? 1 : 0), air_date: /^\d{4}-\d{2}-\d{2}$/.test(ad) ? ad : '' } }];

// One item per episode: each new link, plus the brief (if any). Skips links that already have a live or scheduled episode.
// Air date: the first episode gets the date asked for; the rest go on the release days after it.
const req = $('Check Requester').first().json;
const norm = u => String(u || '').trim().replace(/[?#].*$/, '').replace(/\/+$/, '').toLowerCase();
const done = new Set($input.all().map(i => i.json).filter(r => r && r.source_url && ['published', 'scheduled'].includes(r.status)).map(r => norm(r.source_url)));
const out = [];
const date = () => !req.air_date ? '' : (out.length === 0 ? req.air_date : 'after:' + req.air_date);
if (req.brief && req.brief.length >= 200) out.push({ json: { source_url: '', source_type: 'brief', brief: req.brief, air_date: date() } });
for (const url of String(req.link_list || '').split('\n').filter(Boolean)) {
  if (done.has(norm(url))) continue;
  out.push({ json: { source_url: url, source_type: /breakpointsystems\.com/i.test(url) ? 'own' : 'article', brief: '', air_date: date() } });
}
return out;

// Weekly radar pick: take the oldest Breakpoint topic Billy APPROVED in the Topic Radar email
// (n8n table "topic_radar", business = 'bps', status = 'approved'). Never 'suggested' rows: Billy approves every topic.
// A topic is used once: skipped if it already has a handoff_ref, or if our own ledger already logged it (source "radar:<id>").
const rows = $('Get Radar Topics').all().map(i => i.json || {});
const usedRefs = new Set($input.all().map(i => String((i.json || {}).source_url || '')).filter(s => s.startsWith('radar:')));
const list = v => { try { const a = typeof v === 'string' ? JSON.parse(v) : v; return Array.isArray(a) ? a : []; } catch (e) { return []; } };
const pick = rows
  .filter(r => r.business === 'bps' && r.status === 'approved' && !String(r.handoff_ref || '').trim() && !usedRefs.has('radar:' + r.id))
  .sort((a, b) => String(a.decided_et || a.createdAt || '').localeCompare(String(b.decided_et || b.createdAt || '')))[0];
if (!pick) return [{ json: { skip: true, reason: 'No approved Breakpoint radar topic waiting. Approve one in the Monday Topic Radar email, or use the request form.' } }];
// The approved row becomes the episode brief. Its sources are listed so the writer can credit them;
// the strategist's own wording is not treated as verified fact (the script gate still blocks invented numbers).
const brief = [
  'TOPIC: ' + (pick.title || ''),
  'OWNER QUESTION: ' + (pick.primary_question || ''),
  'WHY NOW: ' + (pick.why_now || ''),
  'ANGLE FOR THE EPISODE: ' + (pick.podcast_angle || ''),
  'SHORT ANSWER TO BUILD ON: ' + (pick.extractable_answer || ''),
  'WHAT MAKES OUR TAKE DIFFERENT: ' + (pick.citation_edge || ''),
  'Use only general explanations plus the points above. Do not state statistics, prices or company results unless they appear above.',
  list(pick.source_urls).length ? 'NEWS SOURCES (credit by publication name if used): ' + list(pick.source_urls).join(' ') : ''
].filter(Boolean).join('\n');
return [{ json: { skip: false, radar_id: pick.id, source_url: '', source_type: 'brief', brief, air_date: '', radar_ref: 'radar:' + pick.id, title: pick.title } }];
